  "content.84fee1b908": "شفرات الرياح المتقاطعة",
  "content.21f48f0714": "شفرتان هلاليتان تتقاطعان إلى الخارج، ثم تقطعان الأعداء في مسار عودة منحني.",
  "content.bceb0fd05d": "ملفات تسلا",
  "content.20e9db560e": "تترك ملفات خلفك تصعق الأعداء القريبين وتكهرب الخط بينها وبين الملف السابق.",
  "content.3fa4624af4": "صواريخ السرب",
  "content.d5a30861d8": "تطلق صواريخ صغيرة موجّهة في موجة متتابعة، وتغمر الحشود بانفجارات صغيرة.",
  "content.33308c454a": "شظايا المنشور",
  "content.7b8ce4b3a3": "بلورات ترتد بين الأعداء، وتنقسم كل منها إلى بلورتين أصغر عند أول إصابة.",
  "content.6ae4da1570": "السوط الشعاعي",
  "content.dda58a2099": "الزر الأيسر: امسح بقوس واسع بشعاع مرن. كل ضربة تصيب العدو مرة واحدة.",
  "content.d20d4a8f64": "الحارس المحمول",
  "content.5191e9018c": "الزر الأيمن: انشر برجًا عند المؤشر يتعقّب الأعداء ويطلق عليهم. نشر برج آخر يستبدل الأقدم.",
  "content.b2ecb120df": "العاصفة الزجاجية",
  "content.1519201745": "دمج شفرات الرياح المتقاطعة وشظايا المنشور. تنفجر الشفرات الهلالية بومضات بلورية، وترتد الشظايا المتشعبة بين الحشود.",
  "content.1ded80863d": "شبكة الدبابير",
  "content.5085777882": "دمج ملفات تسلا وصواريخ السرب. بطارية صواريخ كهربائية تنقل انفجاراتها البرق بين الأعداء القريبين، فيما تحرس الملفات مسارك.",
  "content.7bd71968dd": "خلية الرد",
  "content.f9fa5592c1": "تيار الانزلاق",
