  "content.1b913d3b3f": "امسح بقوس واسع بشعاع مرن. كل ضربة تصيب العدو مرة واحدة.",
  "content.a0fe8c20b1": "انشر برجًا عند المؤشر يتعقّب الأعداء ويطلق عليهم. نشر برج آخر يستبدل الأقدم.",
  "content.672418ed7d": "الصدّ: تضيف الإصابات +⟪0⟫ ضرر لمدة ⟪1⟫ ث. ضعه قبل المضاعفات.",
  "content.9ec4a01350": "اندفاعة مثالية: إصابات المدار والأثر تسبب +⟪0⟫% ضرر لمدة ⟪1⟫ ث.",
  "content.f6d86f700c": "استخدم قدرتك القصوى: +⟪0⟫% ضرر لمدة ⟪1⟫ ث.",
  "content.3347d5257c": "اصرف الكومبو: تضيف الإصابات +⟪0⟫ ضرر لمدة ⟪1⟫ ث. بلا مكافأة ذهب.",
  "content.73023179eb": "بعد انتهاء الإرجاع: +⟪0⟫% ضرر لمدة ⟪1⟫ ث.",
  "content.9f02fc66b3": "انجُ من الخروج من الآلي: +⟪0⟫% ضرر لمدة ⟪1⟫ ث، بما فيه انفجار القذف.",
  "content.c21d055973": "افتح صندوقًا: موجة صاعقة بنصف قطر ⟪0⟫ م تسبب ⟪1⟫ ضرر.",
  "content.4796d804bf": "داخل نار حذاء اللهب: إصابات النار والأثر تسبب +⟪0⟫% ضرر.",
  "content.1c57742cae": "على بُعد ⟪0⟫ م من ساتر: إصابات المدار والمنطقة تسبب +⟪1⟫% ضرر.",
  "content.b1bbcf2021": "على بُعد ⟪0⟫ م أو أكثر: إصابات الصقيع والسلسلة تسبب +⟪1⟫% ضرر.",
  "content.a58a60981e": "كل إصابة +⟪0⟫ ضرر. الصحة القصوى ×⟪1⟫. ضعه قبل المضاعفات.",
  "content.5e37395e25": "تخسر كل إصابة ⟪0⟫ ضرر، ثم تُضرب في ⟪1⟫. الإصابات القوية تكسب؛ والترتيب مهم.",
  "content.352a455638": "حروقك تمنح الحلفاء +⟪0⟫% فرصة إصابة حرجة ضد ذلك العدو (سقف الفريق +⟪1⟫%).",
  "content.0836247367": "الحلفاء الآخرون ضمن ⟪0⟫ م يعيدون تلقيم جميع الأسلحة أسرع بنسبة ⟪1⟫% (سقف سرعة الفريق +⟪2⟫%).",
  "content.e76459c2b5": "إذا صدّ حليف ضمن ⟪0⟫ م، تطلق موجة صاعقة بنصف قطر ⟪1⟫ م تسبب ⟪2⟫ ضرر. انتظار ⟪3⟫ ث.",
  "content.87006ad396": "شارك ⟪0⟫% من الصحة التي تستعيدها فعليًا بالشفاء عند القتل مع كل حليف ضمن ⟪1⟫ م (السقف ⟪2⟫%).",
  "content.5cb95a9e84": "إذا نفّذ حليف اندفاعة مثالية ضمن ⟪0⟫ م، تحصل على حصانة لمدة ⟪1⟫ ث (السقف ⟪2⟫ ث). انتظار ⟪3⟫ ث.",
  "content.07d6955765": "إذا استخدم حليف قدرته القصوى ضمن ⟪0⟫ م، تسبب إصاباتك +⟪1⟫% ضرر لمدة ⟪2⟫ ث.",
