  "text.weekly_co_op_this_week_s_seed_and_rules_for_ever_633f78": "تعاوني أسبوعي: خريطة وقواعد موحدة لكل الفرق هذا الأسبوع، وتجهيزات المبتدئ للجميع ولوحة نتائج للفرق.",
  "text.versus_swarm_one_player_is_the_overlord_and_send_44cae9": "مواجهة الحشود: يرسل لاعب موجات الأعداء من الأعلى بصفته السيد الأعلى، وعلى البقية الصمود وهزيمة الزعيم.",
  "text.everyone_plays_the_same_stage_alone_and_builds_u_a2df5a": "يلعب الجميع المرحلة نفسها منفردين ويجمعون التجهيزات، ثم يتواجهون في حلبة واحدة. آخر صامد يفوز.",
