  "text.no_left_click_weapon_use_your_right_click_and_sp_8ad679": "بلا سلاح أيسر. استخدم الأيمن والقدرة الخاصة!",
  "text.elite_parade_cfcb04": "موكب النخبة",
  "text.every_normal_director_spawn_is_an_elite_5969da": "كل عدو عادي في الموجات يصبح نخبة.",
  "text.one_hit_wonder_e75450": "ضربة واحدة",
  "text.any_unblocked_hit_is_lethal_revives_still_work_ea75a7": "أي ضربة غير مصدودة قاتلة. الإحياء ما زال يعمل.",
  "text.bullet_carnival_8737a1": "كرنفال الطلقات",
  "text.enemy_shots_travel_twice_as_fast_8e413e": "طلقات الأعداء بضعف السرعة.",
  "text.level_up_5b0ee6": "ارتفع المستوى!",
  "text.pick_1_of_3_cards_click_or_keys_1_3_the_ribbon_a_c71357": "اختر بطاقة من 3 (بالنقر أو مفاتيح 1-3). يوضح الشريط السفلي ما ترقيه: الأيسر أو الأيمن أو القدرة الخاصة أو السلاح الآلي أو الأداة.",
  "text.evolution_fork_634218": "مسارا التطور",
  "text.enough_ranks_to_evolve_pick_one_of_the_two_forms_2fd106": "لديك رتب كافية للتطور! اختر شكلا واحدا من اثنين. يغيّر كل شكل طريقة عمل الأداة ويضيف وسما تستفيد منه تعديلات جديدة.",
  "text.the_shop_37cbe7": "المتجر",
  "text.mods_sit_in_5_slots_and_change_how_your_damage_w_71e69c": "تحتل التعديلات 5 خانات وتغير طريقة حساب الضرر. الذهب المدخر يمنح عائدا عند إنهاء كل مرحلة، لذا قد يفيدك الادخار.",
  "text.mod_order_matters_7598df": "ترتيب التعديلات مهم",
  "text.damage_flows_through_your_mods_left_to_right_dam_1e221f": "يمر الضرر عبر التعديلات من اليسار إلى اليمين: (الضرر + الإضافات) × المضاعفات. انقل إضافات الضرر الثابتة قبل المضاعفات بالأسهم. الصدى ينسخ التعديل إلى يمينه.",
  "text.elite_07576c": "نخبة!",
  "text.a_big_tough_enemy_with_a_modifier_shield_fast_sp_891aa6": "عدو ضخم وقوي بميزة إضافية (درع أو سرعة أو انقسام...). شريط الجمجمة يوضح صحته. اهزمه لصندوق كنز.",
  "text.exposed_e6c328": "انكشاف",
  "text.right_click_hits_expose_enemies_30_damage_from_e_38bc87": "ضربات الأيمن تكشف الأعداء: +30% ضرر من الجميع لمدة 4ث. افتتح بالأيمن وأنه بالأيسر.",
  "text.burn_ticks_damage_shock_makes_enemies_take_20_fr_22dfd5": "الحرق يلحق ضررا مستمرا، والصعق يزيد الضرر المتلقى 20%، والتجميد يوقف العدو. اجمع تأثيرين على عدو لتركيبة.",
  "text.status_combo_f68922": "تركيبة تأثيرات!",
  "text.burn_shock_overload_blast_kill_a_frozen_enemy_sh_c6ed94": "حرق + صعق = انفجار فرط شحن. قتل مجمد = تحطيم. تفجير محترق = نابالم. يمكن للتعديلات تقوية كل منها.",
  "text.it_changes_its_attacks_at_66_and_33_life_red_zon_bf37e5": "يغيّر هجماته عند 66% و33% صحة. المناطق والخطوط الحمراء تنذر بالهجوم: اندفع عبرها (⟪0⟫) أو صد الطلقات (⟪1⟫).",
  "text.treasure_chest_81663c": "صندوق كنز",
  "text.walk_into_it_for_a_free_item_on_the_spot_the_arr_3230d7": "امش نحوه لتحصل على أداة مجانية فورا. يشير سهم حافة الشاشة إلى أقرب صندوق.",
  "text.special_ready_f6a478": "القدرة الخاصة جاهزة",
  "text.press_or_middle_click_for_your_special_it_rechar_03aa5b": "اضغط ⟪0⟫ (أو الزر الأوسط) لقدرتك الخاصة. تشحن بمرور الوقت.",
  "text.ultimate_ready_d08f2b": "القدرة النهائية جاهزة",
  "text.press_perfect_dodges_parries_and_kills_charge_yo_916d6b": "اضغط ⟪0⟫! التفادي والصد المثالي والقتل يشحنون قدرة بطلك النهائية.",
  "text.style_meter_8e60e9": "مقياس الأسلوب",
  "text.fast_kills_perfect_dodges_and_parries_raise_your_9b344a": "القتل السريع والتفادي والصد المثالي يرفعون أسلوبك من D إلى SS. الأسلوب الأعلى يزيد النقاط والخبرة. الإصابة تخفضه.",
  "text.gear_f7f969": "ترس",
  "text.each_gear_rerolls_one_set_of_level_up_cards_on_t_5e783d": "كل ترس يبدل مجموعة بطاقات مستوى واحدة (⟪0⟫ في شاشة رفع المستوى).",
  "text.stage_clear_4e29fa": "اكتملت المرحلة",
  "text.walk_into_the_portal_for_the_next_stage_every_st_adf1cd": "اعبر البوابة للمرحلة التالية. تزداد الصعوبة كل مرحلة، وتنتهي كل رابعة بالزعيم الأخير.",
  "text.a_teammate_revives_you_by_standing_next_to_you_f_b91da8": "يحييك زميل بالوقوف بجانبك 3ث. انقر لمشاهدة زميل آخر أثناء الانتظار.",
  "text.teammate_down_47afc6": "سقط زميل",
  "text.stand_next_to_them_for_3_s_to_revive_them_you_bo_80d4d7": "قف بجانبه 3ث لإحيائه. تحصلان على حصانة قصيرة.",
  "text.walk_around_with_or_the_left_stick_you_always_fa_4087eb": "تحرك بـ⟪0⟫ ⟪1⟫ ⟪2⟫ ⟪3⟫ أو العصا اليسرى. تواجه دائما جهة تصويبك.",
  "text.aim_and_fire_e2180c": "صوّب وأطلق",
  "text.aim_with_the_mouse_or_right_stick_and_hold_left__395851": "صوّب بالفأرة (أو العصا اليمنى) واضغط الأيسر لإطلاق ⟪0⟫. حطم ⟪1⟫ روبوتات تدريب.",
  "text.hold_right_click_or_x_for_your_its_hits_expose_e_c35ec0": "اضغط الأيمن (أو X) لاستخدام ⟪0⟫. ضرباته تكشف الأعداء: +30% ضرر من الجميع 4ث. اكشف الروبوت الكبير.",
  "text.press_to_dash_you_can_t_be_hit_mid_dash_dash_thr_ff9c38": "اضغط ⟪0⟫ للاندفاع؛ لا تُصاب أثناءه. اندفع عبر طلقة وردية قبل أن تصيبك مباشرة.",
  "text.press_or_b_right_as_a_pink_shot_reaches_you_to_p_99aaf3": "اضغط ⟪0⟫ (أو B) لحظة وصول الطلقة الوردية لصدها إلى مطلقها.",
  "text.your_special_is_ready_press_or_rb_to_set_off_you_fa2e3b": "قدرتك الخاصة جاهزة: اضغط ⟪0⟫ (أو RB) لتفعيل ⟪1⟫ قرب الروبوتات. تشحن بمرور الوقت.",
  "text.ultimate_df1d2d": "القدرة النهائية",
  "text.perfect_dodges_parries_and_kills_charge_your_her_5caa68": "التفادي والصد المثالي والقتل يشحنون النهائية. امتلأت: اضغط ⟪0⟫ (أو R3).",
  "text.level_up_529820": "رفع المستوى",
  "text.kills_drop_xp_gems_that_fly_to_you_a_full_xp_bar_8d848d": "يسقط الأعداء جواهر خبرة تطير إليك. امتلاء الشريط يرفع مستواك: اختر بطاقة من 3. يوضح الشريط ما ترقيه.",
  "text.chests_pop_up_on_the_map_every_30_s_the_arrow_at_2bf388": "تظهر صناديق بالخريطة كل 30ث (يشير سهم الحافة إليها). امش نحو هذا الصندوق لأداة مجانية.",
