  "text.the_same_seed_and_rules_for_every_team_everyone__11679b": ": بذرة وقواعد موحدة لكل الفرق. ⟪1⟫ يبدأ الجميع بالمبتدئ. استضف مباراة مع النمط الأسبوعي، أو العب في التعاون المحلي.",
