  "text.could_not_reach_that_game_check_the_code_and_try_0d17dd": "تعذر الوصول إلى المباراة. تحقق من الرمز وحاول مجددا.",
  "text.found_the_game_but_could_not_connect_one_of_your_c90e43": "عثرنا على المباراة لكن تعذر الاتصال: إحدى الشبكتين تمنع الاتصال المباشر. اضبط مرحّلا مخصصا (خادم TURN) أدناه، أو جرّب شبكة أخرى.",
  "text.found_the_game_but_could_not_connect_even_throug_0a99b8": "عثرنا على المباراة لكن تعذر الاتصال حتى عبر المرحّل. تحقق من إعداداته أو جرّب شبكة أخرى.",
  "text.no_game_found_with_that_code_ca3427": "لا توجد مباراة بهذا الرمز.",
  "text.that_code_is_taken_try_hosting_again_a09915": "هذا الرمز مستخدم. حاول استضافة مباراة جديدة.",
  "text.could_not_reach_the_matchmaking_server_check_you_8f1b9d": "تعذر الوصول إلى خادم العثور على المباريات. تحقق من اتصالك بالإنترنت.",
  "text.this_browser_does_not_support_online_play_98b5e8": "هذا المتصفح لا يدعم اللعب عبر الإنترنت.",
  "text.connection_problem_please_try_again_d7caa1": "مشكلة في الاتصال. حاول مجددا.",
